package dev.risingheroes.core;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class HeroRulesTest {
    private HeroProfile hero(){var p=new HeroProfile();HeroRules.firstAssignment(p,List.of("explosion"),new Random(4));return p;}
    @Test void assignmentIsExactlyOnceEvenWithDifferentRandomSeed(){var p=hero();p.masteries.put("explosion",17);assertFalse(HeroRules.firstAssignment(p,List.of("other"),new Random(1)));assertEquals("explosion",p.quirk);assertEquals(17,p.mastery());}
    @Test void emptyStartingPoolCannotCreateAQuirklessFreeRoll(){var p=new HeroProfile();assertThrows(IllegalArgumentException.class,()->HeroRules.firstAssignment(p,List.of(),new Random()));assertTrue(p.quirk.isEmpty());}
    @Test void creativeTokensRequireCreativeModeOrOperatorPermission(){assertFalse(HeroRules.mayUseCreativeToken(false,0));assertFalse(HeroRules.mayUseCreativeToken(false,1));assertTrue(HeroRules.mayUseCreativeToken(true,0));assertTrue(HeroRules.mayUseCreativeToken(false,2));}
    @Test void assignmentRestoresArchiveWithoutResettingGlobalProgressOrExhaustion(){var p=hero();p.masteries.put("explosion",42);p.masteries.put("synthetic_test_quirk",9);p.credits=37;p.schoolStage=3;p.stamina=19;p.strain=70;p.cooldowns.put("palm_burst",1000L);HeroRules.assign(p,"synthetic_test_quirk");assertEquals(9,p.mastery());HeroRules.assign(p,"explosion");assertEquals(42,p.mastery());assertEquals(37,p.credits);assertEquals(3,p.schoolStage);assertEquals(19,p.stamina);assertEquals(70,p.strain);assertEquals(1000L,p.cooldowns.get("palm_burst"));}
    @Test void spoofedLockedMoveCannotBeEquippedOrCast(){var p=hero();assertThrows(IllegalArgumentException.class,()->HeroRules.equip(p,1,"howitzer_impact",100));p.slots.set(0,"howitzer_impact");assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,false));assertEquals(100,p.stamina);}
    @Test void masteryAloneDoesNotBypassARelevantTrial(){var p=hero();p.masteries.put("explosion",100);HeroRules.unlockEarned(p);assertFalse(p.currentUnlocks().contains("ap_shot"));p.trials.add("control");HeroRules.unlockEarned(p);assertTrue(p.currentUnlocks().contains("ap_shot"));assertFalse(p.currentUnlocks().contains("howitzer_impact"));}
    @Test void acceptedStartupPaysCostsAndCooldownExactlyOnce(){var p=hero();HeroRules.reserveCast(p,0,100,false,false,false);assertEquals(88,p.stamina);assertEquals(12,p.strain);assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,101,true,false,false));assertEquals(88,p.stamina);assertEquals(124L,p.cooldowns.get("palm_burst"));}
    @Test void recoveryCooldownAndResourceCapsAreIndependentChecks(){var p=hero();p.exertionUntil=110;assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,false));p.exertionUntil=0;p.cooldowns.put("palm_burst",110L);assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,false));p.cooldowns.clear();p.strain=95;assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,false));p.strain=0;p.stamina=3;assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,false));}
    @Test void airborneAndUnderwaterRulesCannotBeSkipped(){var p=hero();p.currentUnlocks().add("aerial_redirection");p.slots.set(4,"aerial_redirection");assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,4,100,false,false,false));assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,true,true));}
    @Test void slotTypesAndAbilityCooldownSurviveLoadoutEdits(){var p=hero();p.currentUnlocks().add("recoil_dodge");p.cooldowns.put("recoil_dodge",400L);assertThrows(IllegalArgumentException.class,()->HeroRules.equip(p,4,"recoil_dodge",200));HeroRules.equip(p,1,"recoil_dodge",200);assertEquals(400L,p.cooldowns.get("recoil_dodge"));}
    @Test void singleQuirkRerollDoesNotConsumeAToken(){var p=hero();HeroRules.grantToken(p);assertThrows(IllegalArgumentException.class,()->HeroRules.beginReroll(p,List.of("explosion"),100,false,new Random()));assertEquals(1,p.liveTokens.size());assertTrue(p.offers.isEmpty());}
    @Test void offersAreDistinctExcludeCurrentAndConsumeOneCredential(){var p=hero();HeroRules.grantToken(p);HeroRules.grantToken(p);var offers=HeroRules.beginReroll(p,List.of("explosion","test_a","test_b","test_b","test_c","test_d"),100,false,new Random(4));assertEquals(3,offers.size());assertEquals(3,new HashSet<>(offers).size());assertFalse(offers.contains("explosion"));assertEquals(1,p.liveTokens.size());}
    @Test void reopeningAndReconnectRetainTheSameOffersAndCost(){var p=hero();HeroRules.grantToken(p);var offers=HeroRules.beginReroll(p,List.of("explosion","test_a","test_b"),100,false,new Random(1));var restored=Catalog.JSON.fromJson(Catalog.JSON.toJson(p),HeroProfile.class);assertEquals(offers,HeroRules.beginReroll(restored,List.of("test_c"),200,false,new Random(999)));assertTrue(restored.liveTokens.isEmpty());assertEquals(p.offerIdentity,restored.offerIdentity);}
    @Test void keepingQuirkStillSpendsTokenAndCannotRepeatSelection(){var p=hero();HeroRules.grantToken(p);HeroRules.beginReroll(p,List.of("explosion","test_a"),100,false,new Random());String offer=p.offerIdentity;HeroRules.chooseReroll(p,offer,"keep",100);assertEquals("explosion",p.quirk);assertTrue(p.liveTokens.isEmpty());assertThrows(IllegalArgumentException.class,()->HeroRules.chooseReroll(p,offer,"test_a",100));}
    @Test void staleOrUnadvertisedChoiceCannotChangeQuirk(){var p=hero();HeroRules.grantToken(p);HeroRules.beginReroll(p,List.of("explosion","test_a"),100,false,new Random());assertThrows(IllegalArgumentException.class,()->HeroRules.chooseReroll(p,"old_offer","test_a",100));assertThrows(IllegalArgumentException.class,()->HeroRules.chooseReroll(p,p.offerIdentity,"not_offered",100));assertEquals("explosion",p.quirk);}
    @Test void smallPoolsReturnFewerOffers(){var p=hero();HeroRules.grantToken(p);assertEquals(List.of("test_a"),HeroRules.beginReroll(p,List.of("explosion","test_a"),100,false,new Random()));}
    @Test void combatBlocksRerollsAndLoadoutChangesWithoutCost(){var p=hero();HeroRules.grantToken(p);p.combatUntil=200;assertThrows(IllegalArgumentException.class,()->HeroRules.beginReroll(p,List.of("test_a"),100,false,new Random()));assertThrows(IllegalArgumentException.class,()->HeroRules.equip(p,0,"palm_burst",100));assertEquals(1,p.liveTokens.size());}
    @Test void uniqueRewardsCannotDuplicateCreditsMasteryOrRank(){var p=hero();assertTrue(HeroRules.reward(p,"mission:one",5,100));assertFalse(HeroRules.reward(p,"mission:one",5,100));assertEquals(5,p.mastery());assertEquals(100,p.credits);}
    @Test void unknownSaveVersionIsRejectedInsteadOfReset(){var p=hero();p.version=99;assertThrows(IllegalArgumentException.class,p::validate);}
    @Test void copyCannotMutateLiveStateBeforeCommit(){var p=hero();var copy=p.copy();copy.masteries.put("explosion",100);copy.currentUnlocks().add("howitzer_impact");assertEquals(0,p.mastery());assertFalse(p.currentUnlocks().contains("howitzer_impact"));}
    @Test void dataRejectsDuplicateMovesAndUnboundedRanges(){var m=Catalog.move("palm_burst");assertThrows(IllegalArgumentException.class,()->Catalog.validate(List.of(m,m)));var invalid=new Move(m.id(),m.name(),m.slot(),m.shape(),4,1,8,12,12,24,Double.NaN,5,0,"",m.description());assertThrows(IllegalArgumentException.class,invalid::validate);}
}
